surahs_meta = [
  (1, '001', 'سورة الفاتحة', 'Al-Fatihah', 7, 'مكية', False, 'بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ (1) الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ (2) الرَّحْمَٰنِ الرَّحِيمِ', 'أم الكتاب وأعظم سور القرآن الكريم. ركن الصلاة الذي لا تصح إلا به.', 'في «مجمع البيان» لأمين الإسلام الطبرسي: سورة الفاتحة مكية بإجماع، وهي سبع آيات وتسمى أم الكتاب لاشتمالها على مجمل معاني القرآن.'),
  (2, '002', 'سورة البقرة', 'Al-Baqarah', 286, 'مدنية', True, 'الم (1) ذَٰلِكَ الْكِتَابُ لَا رَيْبَ ۛ فِيهِ ۛ هُدًى لِّلْمُتَّقِينَ (2) الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ', 'سنام القرآن وأطول سوره، فيها آية الكرسي وخواتيم البقرة وأحكام الشريعة.', 'في «مجمع البيان» للطبرسي: سورة البقرة مدنية، أطول سور القرآن وفيها أعظم آية وهي آية الكرسي.'),
  (3, '003', 'سورة آل عمران', 'Ali \'Imran', 200, 'مدنية', True, 'الم (1) اللَّهُ لَا إِلَٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ (2) نَزَّلَ عَلَيْكَ الْكِتَابَ بِالْحَقِّ', 'سورة التوحيد والثبات، فيها آية المباهلة وآية الاعتصام بحبل الله جميعاً.', 'في «مجمع البيان» للطبرسي: سورة آل عمران مدنية مئتا آية، تفيض ببيان التوحيد وحوار أهل الكتاب والمباهلة.'),
  (4, '004', 'سورة النساء', 'An-Nisa', 176, 'مدنية', True, 'يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُم مِّن نَّفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا', 'تنظيم الأسرة وحقوق النساء واليتامى وإقامة القضاء العادل وطاعة أولي الأمر.', 'في «مجمع البيان» للطبرسي: سورة النساء مدنية، افتتحت بالأمر بالتقوى وصلة الأرحام وفصلت أحكام المواريث والعدل.'),
  (5, '005', 'سورة المائدة', 'Al-Ma\'idah', 120, 'مدنية', True, 'يَا أَيُّهَا الَّذِينَ آمَنُوا أَوْفُوا بِالْعُقُودِ ۚ أُحِلَّتْ لَكُم بَهِيمَةُ الْأَنْعَامِ إِلَّا مَا يُتْلَىٰ عَلَيْكُمْ', 'سورة العقود، فيها آية إكمال الدين والولاية وآية التبليغ ومائدة عيسى عليه السلام.', 'في «مجمع البيان» للطبرسي: سورة المائدة مدنية من آخر ما نزل، فيها عهود الإيمان وأحكام الحلال والحرام والولاية.'),
  (6, '006', 'سورة الأنعام', 'Al-An\'am', 165, 'مكية', True, 'الْحَمْدُ لِلَّهِ الَّذِي خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ وَجَعَلَ الظُّلُمَاتِ وَالنُّورَ', 'سورة التوحيد العظمى ومحاجة المشركين، نزلت جملة واحدة يشيعها سبعون ألف ملك.', 'في «مجمع البيان» للطبرسي: سورة الأنعام مكية نزلت جملة واحدة يشيعها سبعون ألف ملك، وهي سورة البراهين الكبرى.'),
  (7, '007', 'سورة الأعراف', 'Al-A\'raf', 206, 'مكية', True, 'المص (1) كِتَابٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِي صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِ وَذِكْرَىٰ لِلْمُؤْمِنِينَ', 'صراع الحق والباطل، وقصص الأنبياء، وأصحاب الأعراف وميثاق الذر الأول.', 'في «مجمع البيان»: سورة الأعراف مكية، بيّن فيها الطبرسي تفاصيل ميثاق الذر ومصير أهل الأعراف بين الجنة والنار.'),
  (8, '008', 'سورة الأنفال', 'Al-Anfal', 75, 'مدنية', True, 'يَسْأَلُونَكَ عَنِ الْأَنفَالِ ۖ قُلِ الْأَنفَالُ لِلَّهِ وَالرَّسُولِ ۖ فَاتَّقُوا اللَّهَ وَأَصْلِحُوا ذَاتَ بَيْنِكُمْ', 'أحكام الجهاد والغنائم ويوم الفرقان في معركة بدر الكبرى وإعداد القوة.', 'في «مجمع البيان»: سورة الأنفال مدنية نزلت في بدر، بيّن فيها الطبرسي قسمة الأنفال ولزوم طاعة الله ورسوله.'),
  (9, '009', 'سورة التوبة', 'At-Tawbah', 129, 'مدنية', False, 'بَرَاءَةٌ مِّنَ اللَّهِ وَرَسُولِهِ إِلَى الَّذِينَ عَاهَدتُّم مِّنَ الْمُشْرِكِينَ', 'البراءة من المشركين والتحذير من النفاق، نزلت بالسيف بلا بسملة لرفع الأمان.', 'في «مجمع البيان»: سورة التوبة مدنية نزلت بلا بسملة لأن البسملة أمان ورحمة وهذه نزلت بالسيف ونبذ العهود.'),
  (10, '010', 'سورة يونس', 'Yunus', 109, 'مكية', True, 'الر ۚ تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ (1) أَكَانَ لِلنَّاسِ عَجَبًا أَنْ أَوْحَيْنَا إِلَىٰ رَجُلٍ مِّنْهُمْ', 'التوحيد والقدر وإعجاز القرآن وسنة الله في نجاة قوم يونس بإيمانهم الصادق.', 'في «مجمع البيان»: سورة يونس مكية، تركز على الحكمة الإلهية في البعثة وإنقاذ قوم يونس بعد توبتهم.'),
  (11, '011', 'سورة هود', 'Hud', 123, 'مكية', True, 'الر ۚ كِتَابٌ أُحْكِمَتْ آيَاتُهُ ثُمَّ فُصِّلَتْ مِن لَّدُنْ حَكِيمٍ خَبِيرٍ', 'قصص الأنبياء ونصرهم والاستقامة وثبات المؤمنين {فَاسْتَقِمْ كَمَا أُمِرْتَ}.', 'في «مجمع البيان»: سورة هود مكية، قال النبي ﷺ: شيبتني هود وأخواتها لما فيها من الأمر الحاسم بالاستقامة.'),
  (12, '012', 'سورة يوسف', 'Yusuf', 111, 'مكية', True, 'الر ۚ تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ (1) إِنَّا أَنزَلْنَاهُ قُرْآنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'أحسن القصص، العفة والصبر والنصر بعد البلاء وتمكين الله للمتقين.', 'في «مجمع البيان»: سورة يوسف مكية، سميت أحسن القصص لجمعها العبر والمواعظ وحسن العاقبة للمتوكلين.'),
  (13, '013', 'سورة الرعد', 'Ar-Ra\'d', 43, 'مدنية', True, 'المر ۚ تِلْكَ آيَاتُ الْكِتَابِ ۗ وَالَّذِي أُنزِلَ إِلَيْكَ مِن رَّبِّكَ الْحَقُّ وَلَٰكِنَّ أَكْثَرَ النَّاسِ لَا يُؤْمِنُونَ', 'قوانين التغيير والآفاق الكونية والاطمئنان بذكر الله {أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ}.', 'في «مجمع البيان»: سورة الرعد مدنية، فيها تسبيح الرعد بحمده وآية طمأنينة القلوب بذكره سبحانه.'),
  (14, '014', 'سورة إبراهيم', 'Ibrahim', 52, 'مكية', True, 'الر ۚ كِتَابٌ أَنزَلْنَاهُ إِلَيْكَ لِتُخْرِجَ النَّاسَ مِنَ الظُّلُمَاتِ إِلَى النُّورِ بِإِذْنِ رَبِّهِمْ', 'رسالة النور والظلمات ودعاء إبراهيم للبلد الحرام ومثل الكلمة الطيبة.', 'في «مجمع البيان»: سورة إبراهيم مكية، تضمنت مثل الكلمة الطيبة كشجرة طيبة ودعوات إبراهيم الخليل لأمته.'),
  (15, '015', 'سورة الحجر', 'Al-Hijr', 99, 'مكية', True, 'الر ۚ تِلْكَ آيَاتُ الْكِتَابِ وَقُرْآنٍ مُّبِينٍ (1) رُّبَمَا يَوَدُّ الَّذِينَ كَفَرُوا لَوْ كَانُوا مُسْلِمِينَ', 'حفظ القرآن الإلهي {إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ} ومصائر المكذبين.', 'في «مجمع البيان»: سورة الحجر مكية، ضمن الله فيها حفظ القرآن الكريم من كل تحريف وتبديل إلى الأبد.'),
  (16, '016', 'سورة النحل', 'An-Nahl', 128, 'مكية', True, 'أَتَىٰ أَمْرُ اللَّهِ فَلَا تَسْتَعْجِلُوهُ ۚ سُبْحَانَهُ وَتَعَالَىٰ عَمَّا يُشْرِكُونَ', 'سورة النعم الكبرى والامتنان بآلاء الله والأمر بالعدل والإحسان وإيتاء ذي القربى.', 'في «مجمع البيان»: سورة النحل مكية تسمى سورة النعم لكثرة ما عدد الله فيها من آلائه على عباده.'),
  (17, '017', 'سورة الإسراء', 'Al-Isra', 111, 'مكية', True, 'سُبْحَانَ الَّذِي أَسْرَىٰ بِعَبْدِهِ لَيْلًا مِّنَ الْمَسْجِدِ الْحَرَامِ إِلَى الْمَسْجِدِ الْأَقْصَى', 'الإسراء والمعراج وبر الوالدين ومنزلة القرآن وهدايته للتي هي أقوم.', 'في «مجمع البيان»: سورة الإسراء مكية افتتحت بالتسبيح وذكر معجزة الإسراء بالنبي ﷺ إلى المسجد الأقصى.'),
  (18, '018', 'سورة الكهف', 'Al-Kahf', 110, 'مكية', True, 'الْحَمْدُ لِلَّهِ الَّذِي أَنزَلَ عَلَىٰ عَبْدِهِ الْكِتَابَ وَلَمْ يَجْعَل لَّهُ عِوَجًا ۜ', 'العصمة من الفتن، وقصص الفتية وموسى والخضر وذي القرنين والاستمساك بالحق.', 'في «مجمع البيان»: سورة الكهف مكية، يستحب قراءتها يوم الجمعة لما فيها من العصمة والنور بين الجمعتين.'),
  (19, '019', 'سورة مريم', 'Maryam', 98, 'مكية', True, 'كهيعص (1) ذِكْرُ رَحْمَتِ رَبِّكَ عَبْدَهُ زَكَرِيَّا (2) إِذْ نَادَىٰ رَبَّهُ نِدَاءً خَفِيًّا', 'رحمة زكريا وبشارة يحيى ومعجزة ولادة عيسى بن مريم وتنزيه الرحمن عن الولد.', 'في «مجمع البيان»: سورة مريم مكية، تتحدث عن مظاهر الرحمة الإلهية ونقاء العبودية والتنزيه الخالص.'),
  (20, '020', 'سورة طه', 'Taha', 135, 'مكية', True, 'طه (1) مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ (2) إِلَّا تَذْكِرَةً لِّمَن يَخْشَىٰ', 'موسى وخطاب الطور وإبطال السحر ونداء {مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ}.', 'في «مجمع البيان»: سورة طه مكية نزلت تسلية لقلب النبي ﷺ وبيان حنان الربوبية ولطفه بأوليائه.'),
  (21, '021', 'سورة الأنبياء', 'Al-Anbiya', 112, 'مكية', True, 'اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِي غَفْلَةٍ مُّعْرِضُونَ (1) مَا يَأْتِيهِم مِّن ذِكْرٍ مِّن رَّبِّهِم مُّحْدَثٍ إِلَّا اسْتَمَعُوهُ', 'سلسلة الأنبياء ودعاؤهم المستجاب {وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ}.', 'في «مجمع البيان»: سورة الأنبياء مكية تفيض بذكر استجابة الله لدعاء أنبيائه في الكروب والشدائد.'),
  (22, '022', 'سورة الحج', 'Al-Hajj', 78, 'مدنية', True, 'يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ السَّاعَةِ شَيْءٌ عَظِيمٌ', 'مناسك الحج وشهود المنافع وتقوى القلوب والجهاد للدفاع عن الحق.', 'في «مجمع البيان»: سورة الحج مدنية، جمعت بين استحضار أهوال القيامة ومقاصد مناسك الحج الإبراهيمي.'),
  (23, '023', 'سورة المؤمنون', 'Al-Mu\'minun', 118, 'مكية', True, 'قَدْ أَفْلَحَ الْمُؤْمِنُونَ (1) الَّذِينَ هُمْ فِي صَلَاتِهِمْ خَاشِعُونَ (2) وَالَّذِينَ هُمْ عَنِ اللَّغْوِ مُعْرِضُونَ', 'صفات الفلاح الإيماني من الخشوع والأمانة والصدق وإعراض عن اللغو.', 'في «مجمع البيان»: سورة المؤمنون مكية، فصلت صفات المؤمنين الوارثين للفردوس الأعلى.'),
  (24, '024', 'سورة النور', 'An-Nur', 64, 'مدنية', True, 'سُورَةٌ أَنزَلْنَاهَا وَفَرَضْنَاهَا وَأَنزَلْنَا فِيهَا آيَاتٍ بَيِّنَاتٍ لَّعَلَّكُمْ تَذَكَّرُونَ', 'آداب الاستئذان والعفاف وحجاب المؤمنات وآية النور العظمى {اللَّهُ نُورُ السَّمَاوَاتِ وَالْأَرْضِ}.', 'في «مجمع البيان»: سورة النور مدنية، نور الله فيها القلوب بالأحكام الأخلاقية وآية النور الكبرى.'),
  (25, '025', 'سورة الفرقان', 'Al-Furqan', 77, 'مكية', True, 'تَبَارَكَ الَّذِي نَزَّلَ الْفُرْقَانَ عَلَىٰ عَبْدِهِ لِيَكُونَ لِلْعَالَمِينَ نَذِيرًا', 'إعجاز التنزيل وصفات عباد الرحمن الذين يمشون هونا وإذا خاطبهم الجاهلون قالوا سلاما.', 'في «مجمع البيان»: سورة الفرقان مكية، ختمت بأرفع وسام لعباد الرحمن ودعائهم بالتقوى وقرة الأعين.'),
  (26, '026', 'سورة الشعراء', 'Ash-Shu\'ara', 227, 'مكية', True, 'طسم (1) تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ (2) لَعَلَّكَ بَاخِعٌ نَّفْسَكَ أَلَّا يَكُونُوا مُؤْمِنِينَ', 'مواقف الأنبياء ونصرهم ونداء {وَإِنَّ رَبَّكَ لَهُوَ الْعَزِيزُ الرَّحِيمُ}.', 'في «مجمع البيان»: سورة الشعراء مكية، تميزت بتكرار خاتمة نصر الأنبياء بالعزة والرحمة الربانية.'),
  (27, '027', 'سورة النمل', 'An-Naml', 93, 'مكية', True, 'طس ۚ تِلْكَ آيَاتُ الْقُرْآنِ وَكِتَابٍ مُّبِينٍ (1) هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ', 'داود وسليمان وعلم المنطق وملكة سبأ وإتقان الصنع الإلهي المحكم.', 'في «مجمع البيان»: سورة النمل مكية، فيها آية البسملة التامة في كتاب سليمان الحكيم.'),
  (28, '028', 'سورة القصص', 'Al-Qasas', 88, 'مكية', True, 'طسم (1) تِلْكَ آيَاتُ الْكِتَابِ الْمُبِينِ (2) نَتْلُو عَلَيْكَ مِن نَّبَإِ مُوسَىٰ وَفِرْعَوْنَ بِالْحَقِّ', 'قصة موسى من المهد إلى النصر ووعد استخلاف المستضعفين {وَنُرِيدُ أَن نَّمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا}.', 'في «مجمع البيان»: سورة القصص مكية، فيها بشارة التمكين الإلهي للمستضعفين وجعلهم أئمة ووارثين.'),
  (29, '029', 'سورة العنكبوت', 'Al-Ankabut', 69, 'مكية', True, 'الم (1) أَحَسِبَ النَّاسُ أَن يُتْرَكُوا أَن يَقُولُوا آمَنَّا وَهُمْ لَا يُفْتَنُونَ', 'سنة الابتلاء ومثل بيت العنكبوت والجهاد في سبيل الله وتثبيت المؤمنين.', 'في «مجمع البيان»: سورة العنكبوت مكية، بيّنت وهن الالتجاء إلى غير الله كوهن بيت العنكبوت.'),
  (30, '030', 'سورة الروم', 'Ar-Rum', 60, 'مكية', True, 'الم (1) غُلِبَتِ الرُّومُ (2) فِي أَدْنَى الْأَرْضِ وَهُم مِّن بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ', 'سنن التاريخ ووعد غلبة الروم وآيات الفطرة ومودة ورحمة الزواج.', 'في «مجمع البيان»: سورة الروم مكية، تضمنت الإعجاز الغيبي وفطرة الله التي فطر الناس عليها.'),
  (31, '031', 'سورة لقمان', 'Luqman', 34, 'مكية', True, 'الم (1) تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ (2) هُدًى وَرَحْمَةً لِّلْمُحْسِنِينَ', 'وصايا لقمان لابنه في التوحيد والبر وخفض الصوت والتواضع للناس.', 'في «مجمع البيان»: سورة لقمان مكية، رسمت النموذج القرآني للتربية الحكيمة والبر بالوالدين.'),
  (32, '032', 'سورة السجدة', 'As-Sajdah', 30, 'مكية', True, 'الم (1) تَنزِيلُ الْكِتَابِ لَا رَيْبَ فِيهِ مِن رَّبِّ الْعَالَمِينَ', 'خلق الإنسان والنشأة وسجدة التلاوة وإمامة الصابرين بأمر الله.', 'في «مجمع البيان»: سورة السجدة مكية، يستحب قراءتها ليلة الجمعة، وتتضمن آية سجود التلاوة.'),
  (33, '033', 'سورة الأحزاب', 'Al-Ahzab', 73, 'مدنية', True, 'يَا أَيُّهَا النَّبِيُّ اتَّقِ اللَّهَ وَلَا تُطِعِ الْكَافِرِينَ وَالْمُنَافِقِينَ', 'غزوة الخندق وآية التطهير {إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنكُمُ الرِّجْسَ أَهْلَ الْبَيْتِ} وخاتم النبيين.', 'في «مجمع البيان»: سورة الأحزاب مدنية، فيها آية التطهير لأهل البيت وآية الصلاة على النبي والتسليم له.'),
  (34, '034', 'سورة سبأ', 'Saba', 54, 'مكية', True, 'الْحَمْدُ لِلَّهِ الَّذِي لَهُ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَلَهُ الْحَمْدُ فِي الْآخِرَةِ', 'شكر النعمة لداود وسليمان وسيل العرم وزوال البطر والإنعام.', 'في «مجمع البيان»: سورة سبأ مكية، تبين أن الشكر يحفظ النعم وأن الكفران بها يجلب الزوال.'),
  (35, '035', 'سورة فاطر', 'Fatir', 45, 'مكية', True, 'الْحَمْدُ لِلَّهِ فَاطِرِ السَّمَاوَاتِ وَالْأَرْضِ جَاعِلِ الْمَلَائِكَةِ رُسُلًا أُولِي أَجْنِحَةٍ', 'أجنحة الملائكة وافتقار العباد {يَا أَيُّهَا النَّاسُ أَنتُمُ الْفُقَرَاءُ إِلَى اللَّهِ}.', 'في «مجمع البيان»: سورة فاطر مكية، تؤكد حقيقة فقر المخلوقات المطلق وغنى الخالق المتعالي.'),
  (36, '036', 'سورة يس', 'Ya-Sin', 83, 'مكية', True, 'يس (1) وَالْقُرْآنِ الْحَكِيمِ (2) إِنَّكَ لَمِنَ الْمُرْسَلِينَ (3) عَلَىٰ صِرَاطٍ مُّسْتَقِيمٍ', 'قلب القرآن ومشكاة التوحيد والبعث وإحياء العظام الرميم بكن فيكون.', 'في «مجمع البيان»: سورة يس مكية، ورد في الحديث: لكل شيء قلب وقلب القرآن يس، وتفيض بأدلة المعاد.'),
  (37, '037', 'سورة الصافات', 'As-Saffat', 182, 'مكية', True, 'وَالصَّافَّاتِ صَفًّا (1) فَالزَّاجِرَاتِ زَجْرًا (2) فَالتَّالِيَاتِ ذِكْرًا (3) إِنَّ إِلَٰهَكُمْ لَوَاحِدٌ', 'صفوف الملائكة وقصة الذبيح إسماعيل وسلام على المرسلين الأطهار.', 'في «مجمع البيان»: سورة الصافات مكية، تفيض بالتسبيح وسلام الله على رسله وأنبيائه المصطفين.'),
  (38, '038', 'سورة ص', 'Sad', 88, 'مكية', True, 'ص ۚ وَالْقُرْآنِ ذِي الذِّكْرِ (1) بَلِ الَّذِينَ كَفَرُوا فِي عِزَّةٍ وَشِقَاقٍ', 'صبر أيوب وخلافة داود والملك العادل لسليمان وقصة الخلق وإبليس.', 'في «مجمع البيان»: سورة ص مكية، تناولت آداب القضاء والعدل وصبر أولياء الله على المحن.'),
  (39, '039', 'سورة الزمر', 'Az-Zumar', 75, 'مكية', True, 'تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ (1) إِنَّا أَنزَلْنَا إِلَيْكَ الْكِتَابَ بِالْحَقِّ فَاعْبُدِ اللَّهَ مُخْلِصًا', 'الإخلاص لله ورجاء المغفرة {قُلْ يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَىٰ أَنفُسِهِمْ لَا تَقْنَطُوا}.', 'في «مجمع البيان»: سورة الزمر مكية، فيها أرجى آية في كتاب الله لفتح باب التوبة والأمل برحمة الله.'),
  (40, '040', 'سورة غافر', 'Ghafir', 85, 'مكية', True, 'حم (1) تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْعَلِيمِ (2) غَافِرِ الذَّنبِ وَقَابِلِ التَّوْبِ شَدِيدِ الْعِقَابِ', 'غافر الذنب وقابل التوب وحملة العرش ودعاء مؤمن آل فرعون بالثبات.', 'في «مجمع البيان»: سورة غافر مكية، أولى الحواميم المباركة، فيها استغفار الملائكة للمؤمنين التائبين.'),
  (41, '041', 'سورة فصلت', 'Fussilat', 54, 'مكية', True, 'حم (1) تَنزِيلٌ مِّنَ الرَّحْمَٰنِ الرَّحِيمِ (2) كِتَابٌ فُصِّلَتْ آيَاتُهُ قُرْآنًا عَرَبِيًّا لِّقَوْمٍ يَعْلَمُونَ', 'بيان القرآن ودعوة الاستقامة وآيات الآفاق والأنفس {سَنُرِيهِمْ آيَاتِنَا فِي الْآفَاقِ}.', 'في «مجمع البيان»: سورة فصلت مكية، تضمنت دلائل التوحيد في النفس والكون حتى يتبين أنه الحق.'),
  (42, '042', 'سورة الشورى', 'Ash-Shura', 53, 'مكية', True, 'حم (1) عسق (2) كَذَٰلِكَ يُوحِي إِلَيْكَ وَإِلَى الَّذِينَ مِن قَبْلِكَ اللَّهُ الْعَزِيزُ الْحَكِيمُ', 'وحدة الوحي ومبدأ الشورى وآية المودة {قُل لَّا أَسْأَلُكُمْ عَلَيْهِ أَجْرًا إِلَّا الْمَوَدَّةَ فِي الْقُرْبَىٰ}.', 'في «مجمع البيان»: سورة الشورى مكية، فيها فرض مودة قربى النبي ﷺ وأهل بيته كأجر للرسالة الخالدة.'),
  (43, '043', 'سورة الزخرف', 'Az-Zukhruf', 89, 'مكية', True, 'حم (1) وَالْكِتَابِ الْمُبِينِ (2) إِنَّا جَعَلْنَاهُ قُرْآنًا عَرَبِيًّا لَّعَلَّكُمْ تَعْقِلُونَ', 'حقارة زخرف الدنيا ومكانة أم الكتاب عند الله وتكريم أوليائه.', 'في «مجمع البيان»: سورة الزخرف مكية، تبين أن متاع الدنيا زائل وأن كرامة الآخرة للمتقين.'),
  (44, '044', 'سورة الدخان', 'Ad-Dukhan', 59, 'مكية', True, 'حم (1) وَالْكِتَابِ الْمُبِينِ (2) إِنَّا أَنزَلْنَاهُ فِي لَيْلَةٍ مُّبَارَكَةٍ ۚ إِنَّا كُنَّا مُنذِرِينَ', 'الليلة المباركة وفضل إنزال القرآن وبطشة الله بالكافرين وإكرام المتقين.', 'في «مجمع البيان»: سورة الدخان مكية، يستحب قراءتها ليلة الجمعة لنيل المغفرة والسكينة.'),
  (45, '045', 'سورة الجاثية', 'Al-Jathiyah', 37, 'مكية', True, 'حم (1) تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ (2) إِنَّ فِي السَّمَاوَاتِ وَالْأَرْضِ لَآيَاتٍ لِّلْمُؤْمِنِينَ', 'جثو الأمم للحساب وآيات الأكوان والكبرياء لله رب العالمين.', 'في «مجمع البيان»: سورة الجاثية مكية، تصوّر مشهد جثو كل أمة أمام كتاب أعمالها في المحشر.'),
  (46, '046', 'سورة الأحقاف', 'Al-Ahqaf', 35, 'مكية', True, 'حم (1) تَنزِيلُ الْكِتَابِ مِنَ اللَّهِ الْعَزِيزِ الْحَكِيمِ (2) مَا خَلَقْنَا السَّمَاوَاتِ وَالْأَرْضَ إِلَّا بِالْحَقِّ', 'بر الوالدين وحمل الأمهات واستماع الجن للقرآن وصبر أولي العزم من الرسل.', 'في «مجمع البيان»: سورة الأحقاف مكية، أوصت بالوالدين إحساناً ودعت للاقتداء بصبر أولي العزم.'),
  (47, '047', 'سورة محمد', 'Muhammad', 38, 'مدنية', True, 'الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ (1) وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ', 'إحباط عمل الكافرين وهداية المؤمنين ووصف أنهار الجنة ونصرة دين الله.', 'في «مجمع البيان»: سورة محمد مدنية تسمى سورة القتال، تفيض ببيان نصر المؤمنين ومحق الباطل.'),
  (48, '048', 'سورة الفتح', 'Al-Fath', 29, 'مدنية', True, 'إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا (1) لِّيَغْفِرَ لَكَ اللَّهُ مَا تَقَدَّمَ مِن ذَنبِكَ وَمَا تَأَخَّرَ', 'الفتح المبين وسكينة الحديبية وبيعة الرضوان والرحمة والمغفرة العظيمة.', 'في «مجمع البيان»: سورة الفتح مدنية، أنزلها الله بشارة بالفتح والسكينة وإعزاز الدين الحنيف.'),
  (49, '049', 'سورة الحجرات', 'Al-Hujurat', 18, 'مدنية', True, 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا بَيْنَ يَدَيِ اللَّهِ وَرَسُولِهِ ۖ وَاتَّقُوا اللَّهَ', 'سورة الأخلاق، تحريم الغيبة والنميمة والتنابز وميزان {إِنَّ أَكْرَمَكُمْ عِندَ اللَّهِ أَتْقَاكُمْ}.', 'في «مجمع البيان»: سورة الحجرات مدنية، أرست معايير الإخوة الإسلامية وحرمة أعراض المؤمنين.'),
  (50, '050', 'سورة ق', 'Qaf', 45, 'مكية', True, 'ق ۚ وَالْقُرْآنِ الْمَجِيدِ (1) بَلْ عَجِبُوا أَن جَاءَهُم مُّنذِرٌ مِّنْهُمْ', 'عظمة القرآن وقرب الله من حبل الوريد وسكرات الموت والبعث والنشور.', 'في «مجمع البيان»: سورة ق مكية، كان النبي ﷺ يكثر قراءتها في خطب الجمعة والأعياد لترقيق القلوب.'),
  (51, '051', 'سورة الذاريات', 'Adh-Dhariyat', 60, 'مكية', True, 'وَالذَّارِيَاتِ ذَرْوًا (1) فَالْحَامِلَاتِ وِقْرًا (2) فَالْجَارِيَاتِ يُسْرًا (3) فَالْمُقَسِّمَاتِ أَمْرًا', 'قسم الرياح والأرزاق وغاية الخلق {وَمَا خَلَقْتُ الْجِنَّ وَالْإِنسَ إِلَّا لِيَعْبُدُونِ}.', 'في «مجمع البيان»: سورة الذاريات مكية، حددت الهدف الأسمى لوجود الثقلين وهو معرفة الله وعبادته.'),
  (52, '052', 'سورة الطور', 'At-Tur', 49, 'مكية', True, 'وَالطُّورِ (1) وَكِتَابٍ مَّسْطُورٍ (2) فِي رَقٍّ مَّنشُورٍ (3) وَالْبَيْتِ الْمَعْمُورِ', 'قسم الطور وكتاب مسطور ونعيم الأبرار في جنات النعيم والنجاة من عذاب السموم.', 'في «مجمع البيان»: سورة الطور مكية، فيها وعيد شديد بالمكذبين وبشارة كريمة للمؤمنين وذرياتهم.'),
  (53, '053', 'سورة النجم', 'An-Najm', 62, 'مكية', True, 'وَالنَّجْمِ إِذَا هَوَىٰ (1) مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَىٰ (2) وَمَا يَنطِقُ عَنِ الْهَوَىٰ', 'المعراج وسدرة المنتهى وحقيقة الوحي {وَمَا يَنطِقُ عَنِ الْهَوَىٰ} وسجدة التلاوة.', 'في «مجمع البيان»: سورة النجم مكية، فيها سجدة تلاوة واجبة، وتبين عصمة النبي في نطقه وهديه.'),
  (54, '054', 'سورة القمر', 'Al-Qamar', 55, 'مكية', True, 'اقْتَرَبَتِ السَّاعَةُ وَانشَقَّ الْقَمَرُ (1) وَإِن يَرَوْا آيَةً يُعْرِضُوا وَيَقُولُوا سِحْرٌ مُّسْتَمِرٌّ', 'انشقاق القمر وتيسير القرآن للذكر {وَلَقَدْ يَسَّرْنَا الْقُرْآنَ لِلذِّكْرِ فَهَلْ مِن مُّدَّكِرٍ}.', 'في «مجمع البيان»: سورة القمر مكية، تكررت فيها البشارة بتيسير القرآن الكريم للفهم والتلاوة.'),
  (55, '055', 'سورة الرحمن', 'Ar-Rahman', 78, 'مدنية', True, 'الرَّحْمَٰنُ (1) عَلَّمَ الْقُرْآنَ (2) خَلَقَ الْإِنسَانَ (3) عَلَّمَهُ الْبَيَانَ', 'عروس القرآن وآلاء الرحمن وتكرار {فَبِأَيِّ آلَاءِ رَبِّكُمَا تُكَذِّبَانِ} ووصف الجنان.', 'في «مجمع البيان»: سورة الرحمن تسمى عروس القرآن لجمال نظمها وتعدادها لنعم الله في الأرض والجنة.'),
  (56, '056', 'سورة الواقعة', 'Al-Waqi\'ah', 96, 'مكية', True, 'إِذَا وَقَعَتِ الْوَاقِعَةُ (1) لَيْسَ لِوَقْعَتِهَا كَاذِبَةٌ (2) خَافِضَةٌ رَّافِعَةٌ', 'أهوال القيامة وأقسام الناس الثلاثة: السابقون وأصحاب اليمين وأصحاب الشمال.', 'في «مجمع البيان»: سورة الواقعة مكية، قراءتها تورث الأمان والغنى وتقي من الفاقة والحاجة.'),
  (57, '057', 'سورة الحديد', 'Al-Hadid', 29, 'مدنية', True, 'سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ', 'تسبيح الكائنات ومنافع الحديد وإنفاق الأموال ونور المؤمنين يسعى بين أيديهم.', 'في «مجمع البيان»: سورة الحديد مدنية، تبين ميزان الإنفاق وأن الحديد فيه بأس شديد ومنافع للناس.'),
  (58, '058', 'سورة المجادلة', 'Al-Mujadila', 22, 'مدنية', True, 'قَدْ سَمِعَ اللَّهُ قَوْلَ الَّتِي تُجَادِلُكَ فِي زَوْجِهَا وَتَشْتَكِي إِلَى اللَّهِ', 'سمع الله للمشتكية وأحكام الظهار وورود لفظ الجلالة في كل آية من آياتها.', 'في «مجمع البيان»: سورة المجادلة مدنية، تميزت بأن اسم الله مذكور في كل آية من آياتها.'),
  (59, '059', 'سورة الحشر', 'Al-Hashr', 24, 'مدنية', True, 'سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ', 'جلاء بني النضير وخواتيم الحشر وأسماء الله الحسنى العظمى وتدبر القرآن.', 'في «مجمع البيان»: سورة الحشر مدنية، ختمت بأعظم آيات الأسماء والصفات الإلهية الحسنى.'),
  (60, '060', 'سورة الممتحنة', 'Al-Mumtahanah', 13, 'مدنية', True, 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ تُلْقُونَ إِلَيْهِم بِالْمَوَدَّةِ', 'الولاء والبراء وقسط المعاملة مع غير المحاربين وبيعة المؤمنات.', 'في «مجمع البيان»: سورة الممتحنة مدنية، حددت ضوابط العلاقات الإنسانية والعدل مع المسالمين.'),
  (61, '061', 'سورة الصف', 'As-Saff', 14, 'مدنية', True, 'سَبَّحَ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ وَهُوَ الْعَزِيزُ الْحَكِيمُ', 'صفوف الجهاد وبشارة عيسى بالنبي أحمد ﷺ ونصر الله القريب والفتح المبين.', 'في «مجمع البيان»: سورة الصف مدنية، فيها بشارة المسيح بخاتم الأنبياء باسمه الشريف أحمد.'),
  (62, '062', 'سورة الجمعة', 'Al-Jumu\'ah', 11, 'مدنية', True, 'يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ الْمَلِكِ الْقُدُّوسِ الْعَزِيزِ الْحَكِيمِ', 'فضل صلاة الجمعة والسعي لذكر الله وبعثة النبي الأمي يزكيهم ويعلمهم.', 'في «مجمع البيان»: سورة الجمعة مدنية، فرضت السعي لصلاة الجمعة وترك التجارة وقت النداء.'),
  (63, '063', 'سورة المنافقون', 'Al-Munafiqun', 11, 'مدنية', True, 'إِذَا جَاءَكَ الْمُنَافِقُونَ قَالُوا نَشْهَدُ إِنَّكَ لَرَسُولُ اللَّهِ ۗ وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ', 'فضح النفاق وأيمانهم الكاذبة والحث على الصدقة قبل فوات الأجل وحلول المنية.', 'في «مجمع البيان»: سورة المنافقون مدنية، كشفت سرائر النفاق وأمرت بالإنفاق في سبيل الله.'),
  (64, '064', 'سورة التغابن', 'At-Taghabun', 18, 'مدنية', True, 'يُسَبِّحُ لِلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۖ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ', 'يوم التغابن وفوز المتقين والتحذير من فتنة الأموال والأولاد والاستغفار.', 'في «مجمع البيان»: سورة التغابن مدنية، سميت بيوم التغابن لظهور غبن الكفار وفوز المؤمنين.'),
  (65, '065', 'سورة الطلاق', 'At-Talaq', 12, 'مدنية', True, 'يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ', 'أحكام العدة والنفقة وبشارة {وَمَن يَتَّقِ اللَّهَ يَجْعَل لَّهُ مَخْرَجًا وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ}.', 'في «مجمع البيان»: سورة الطلاق مدنية تسمى سورة النساء الصغرى، رغبت بالتقوى ووعدت بالفرج.'),
  (66, '066', 'سورة التحريم', 'At-Tahrim', 12, 'مدنية', True, 'يَا أَيُّهَا النَّبِيُّ لِمَ تُحَرِّمُ مَا أَحَلَّ اللَّهُ لَكَ ۖ تَبْتَغِي مَرْضَاتَ أَزْوَاجِكَ', 'التوبة النصوح ومثل آسية امرأة فرعون ومريم ابنة عمران التي أحصنت فرجها.', 'في «مجمع البيان»: سورة التحريم مدنية، ضربت الأمثال بالصالحات كآسية بنت مزاحم ومريم البتول.'),
  (67, '067', 'سورة الملك', 'Al-Mulk', 30, 'مكية', True, 'تَبَارَكَ الَّذِي بِيَدِهِ الْمُلْكُ وَهُوَ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ (1) الَّذِي خَلَقَ الْمَوْتَ وَالْحَيَاةَ', 'المنجية والواقية من عذاب القبر وتبارك الذي بيده الملك وهو على كل شيء قدير.', 'في «مجمع البيان»: سورة الملك مكية تسمى المنجية؛ فإنها تشفع لصاحبها وتنجيه من عذاب القبر.'),
  (68, '068', 'سورة القلم', 'Al-Qalam', 52, 'مكية', True, 'ن ۚ وَالْقَلَمِ وَمَا يَسْطُرُونَ (1) مَا أَنتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ (2) وَإِنَّ لَكَ لَأَجْرًا غَيْرَ مَمْنُونٍ', 'القسم بالقلم وخلق النبي العظيم {وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ} وقصة أصحاب الجنة.', 'في «مجمع البيان»: سورة القلم مكية، شهد الله فيها لخاتم رسله بأعظم وسام أخلاقي خالد.'),
  (69, '069', 'سورة الحاقة', 'Al-Haqqah', 52, 'مكية', True, 'الْحَاقَّةُ (1) مَا الْحَاقَّةُ (2) وَمَا أَدْرَاكَ مَا الْحَاقَّةُ (3) كَذَّبَتْ ثَمُودُ وَعَادٌ بِالْقَارِعَةِ', 'أهوال الحاقة وهلاك عاد وثمود وأخذ الكتاب باليمين والشمال وتنزيه القرآن.', 'في «مجمع البيان»: سورة الحاقة مكية، سميت الحاقة لأن القيامة تحق فيها الأمور ويجازى كل إنسان.'),
  (70, '070', 'سورة المعارج', 'Al-Ma\'arij', 44, 'مكية', True, 'سَأَلَ سَائِلٌ بِعَذَابٍ وَاقِعٍ (1) لِّلْكَافِرِينَ لَيْسَ لَهُ دَافِعٌ (2) مِّنَ اللَّهِ ذِي الْمَعَارِجِ', 'عذاب واقع ودرجات المعارج وطباع الإنسان والمحافظة على الصلاة والأمانات.', 'في «مجمع البيان»: سورة المعارج مكية، نزلت في شأن من اعترض على ولاية الإمام علي في غدير خم.'),
  (71, '071', 'سورة نوح', 'Nuh', 28, 'مكية', True, 'إِنَّا أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِ أَنْ أَنذِرْ قَوْمَكَ مِن قَبْلِ أَن يَأْتِيَهُمْ عَذَابٌ أَلِيمٌ', 'جهاد نوح وصبره واستغفاره وبركات الاستغفار في الرزق والمطر والأولاد.', 'في «مجمع البيان»: سورة نوح مكية، تضمنت سر الاستغفار العظيم في استنزال الأمطار وتكثير الأموال.'),
  (72, '072', 'سورة الجن', 'Al-Jinn', 28, 'مكية', True, 'قُلْ أُوحِيَ إِلَيَّ أَنَّهُ اسْتَمَعَ نَفَرٌ مِّنَ الْجِنِّ فَقَالُوا إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا', 'استماع الجن للقرآن وانبهارهم به وإيمانهم بالتوحيد الخالص ونفي الشركاء.', 'في «مجمع البيان»: سورة الجن مكية، تروي إيمان وفد الجن بعد استماعهم لتلاوة النبي للقرآن.'),
  (73, '073', 'سورة المزمل', 'Al-Muzzammil', 20, 'مكية', True, 'يَا أَيُّهَا الْمُزَّمِّلُ (1) قُمِ اللَّيْلَ إِلَّا قَلِيلًا (2) نِّصْفَهُ أَوِ انقُصْ مِنْهُ قَلِيلًا', 'قيام الليل وترتيل القرآن وتثبيت القلب للقول الثقيل والصبر الجميل.', 'في «مجمع البيان»: سورة المزمل مكية، أمرت بقيام الليل وترتيل القرآن ترتيلاً لإعداد الروح الرسالية.'),
  (74, '074', 'سورة المدثر', 'Al-Muddathir', 56, 'مكية', True, 'يَا أَيُّهَا الْمُدَّثِّرُ (1) قُمْ فَأَنذِرْ (2) وَرَبَّكَ فَكَبِّرْ (3) وَثِيَابَكَ فَطَهِّرْ', 'نداء النبوة الأول: قم فأنذر وربك فكبر وثيابك فطهر والرجز فاهجر.', 'في «مجمع البيان»: سورة المدثر مكية، صدعت بأمر التبليغ والإنذار وتطهير النفس والعمل لله وحده.'),
  (75, '075', 'سورة القيامة', 'Al-Qiyamah', 40, 'مكية', True, 'لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ (1) وَلَا أُقْسِمُ بِالنَّفْسِ اللَّوَّامَةِ (2) أَيَحْسَبُ الْإِنسَانُ أَلَّن نَّجْمَعَ عِظَامَهُ', 'النفس اللوامة وبنان الإنسان ووجوه يومئذ ناضرة إلى ربها ناظرة وسكرات الموت.', 'في «مجمع البيان»: سورة القيامة مكية، تصوّر سكرات الموت والبعث وإعادة تسوية أدق تفاصيل البنان.'),
  (76, '076', 'سورة الإنسان', 'Al-Insan', 31, 'مدنية', True, 'هَلْ أَتَىٰ عَلَى الْإِنسَانِ حِينٌ مِّنَ الدَّهْرِ لَمْ يَكُن شَيْئًا مَّذْكُورًا (1) إِنَّا خَلَقْنَا الْإِنسَانَ مِن نُّطْفَةٍ', 'نزلت في أهل البيت عليهم السلام وإطعامهم الطعام مسكيناً ويتيماً وأسيراً لوجه الله.', 'في «مجمع البيان»: سورة الإنسان مدنية، نزلت إجماعاً في الإمام علي وفاطمة والحسن والحسين بإطعامهم الطعام.'),
  (77, '077', 'سورة المرسلات', 'Al-Mursalat', 50, 'مكية', True, 'وَالْمُرْسَلَاتِ عُرْفًا (1) فَالْعَاصِفَاتِ عَصْفًا (2) وَالنَّاشِرَاتِ نَشْرًا (3) فَالْفَارِقَاتِ فَرْقًا', 'قسم الملائكة والرياح وبيان يوم الفصل وتكرار {وَيْلٌ يَوْمَئِذٍ لِّلْمُكَذِّبِينَ}.', 'في «مجمع البيان»: سورة المرسلات مكية، تبين عظمة يوم الفصل بين الخلائق ومصير المكذبين.'),
  (78, '078', 'سورة النبأ', 'An-Naba', 40, 'مكية', True, 'عَمَّ يَتَسَاءَلُونَ (1) عَنِ النَّبَإِ الْعَظِيمِ (2) الَّذِي هُمْ فِيهِ مُخْتَلِفُونَ', 'النبأ العظيم وعم يتساءلون والولاية الكبرى وصور القيامة والحدائق الأعنابا.', 'في «مجمع البيان»: سورة النبأ مكية، ورد في الروايات أن النبأ العظيم هو ولاية أمير المؤمنين.'),
  (79, '079', 'سورة النازعات', 'An-Nazi\'at', 46, 'مكية', True, 'وَالنَّازِعَاتِ غَرْقًا (1) وَالنَّاشِطَاتِ نَشْطًا (2) وَالسَّابِحَاتِ سَبْحًا (3) فَالسَّابِقَاتِ سَبْقًا', 'نزع الأرواح وطغيان فرعون وخوف مقام الرب ونهي النفس عن الهوى.', 'في «مجمع البيان»: سورة النازعات مكية، بينت أن الجنة مأوى من خاف مقام ربه ونهى النفس عن الهوى.'),
  (80, '080', 'سورة عبس', '\'Abasa', 42, 'مكية', True, 'عَبَسَ وَتَوَلَّىٰ (1) أَن جَاءَهُ الْأَعْمَىٰ (2) وَمَا يُدْرِيكَ لَعَلَّهُ يَزَّكَّىٰ', 'تذكرة القرآن وتكريم الصحف المطهرة ويوم يفر المرء من أخيه وأمه وأبيه.', 'في «مجمع البيان»: سورة عبس مكية، تبين أن ميزان الكرامة هو التقوى والخشية لا المظاهر الدنيوية.'),
  (81, '081', 'سورة التكوير', 'At-Takwir', 29, 'مكية', True, 'إِذَا الشَّمْسُ كُوِّرَتْ (1) وَإِذَا النُّجُومُ انكَدَرَتْ (2) وَإِذَا الْجِبَالُ سُيِّرَتْ', 'إذا الشمس كورت وموت الطفولة بالوأد ورؤية جبريل في الأفق المبين المطاع.', 'في «مجمع البيان»: سورة التكوير مكية، تصور انقلاب النظام الكوني عند قيام الساعة تصويراً حياً.'),
  (82, '082', 'سورة الانفطار', 'Al-Infitar', 19, 'مكية', True, 'إِذَا السَّمَاءُ انفَطَرَتْ (1) وَإِذَا الْكَوَاكِبُ انتَثَرَتْ (2) وَإِذَا الْبِحَارُ فُجِّرَتْ', 'انفطار السماء ونداء {يَا أَيُّهَا الْإِنسَانُ مَا غَرَّكَ بِرَبِّكَ الْكَرِيمِ} والكرام الكاتبين.', 'في «مجمع البيان»: سورة الانفطار مكية، تخاطب وجدان الإنسان وتذكره بنعم ربه الذي خلقه فسواه.'),
  (83, '083', 'سورة المطففين', 'Al-Mutaffifin', 36, 'مكية', True, 'وَيْلٌ لِّلْمُطَفِّفِينَ (1) الَّذِينَ إِذَا اكْتَالُوا عَلَى النَّاسِ يَسْتَوْفُونَ', 'ويل للمطففين في الكيل والميزان وسجين وكتاب الأبرار في عليين وتسنيم.', 'في «مجمع البيان»: سورة المطففين مكية، حذرت من التلاعب في حقوق العباد وأبانت رفعة كتاب الأبرار.'),
  (84, '084', 'سورة الانشقاق', 'Al-Inshiqaq', 25, 'مكية', True, 'إِذَا السَّمَاءُ انشَقَّتْ (1) وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ (2) وَإِذَا الْأَرْضُ مُدَّتْ', 'انشقاق السماء وكدح الإنسان إلى ربه كدحاً فملاقيه وأخذ كتابه بيمينه.', 'في «مجمع البيان»: سورة الانشقاق مكية، تبين أن الحياة كدح مستمر ينتهي بلقاء الله والجزاء العادل.'),
  (85, '085', 'سورة البروج', 'Al-Buruj', 22, 'مكية', True, 'وَالسَّمَاءِ ذَاتِ الْبُرُوجِ (1) وَالْيَوْمِ الْمَوْعُودِ (2) وَشَاهِدٍ وَمَشْهُودٍ', 'أصحاب الأخدود والصمود على التوحيد واللوح المحفوظ وبطش الرب الشديد.', 'في «مجمع البيان»: سورة البروج مكية، خلدت تضحية المؤمنين وثباتهم على الإيمان في وجه الطغيان.'),
  (86, '086', 'سورة الطارق', 'At-Tariq', 17, 'مكية', True, 'وَالسَّمَاءِ وَالطَّارِقِ (1) وَمَا أَدْرَاكَ مَا الطَّارِقُ (2) النَّجْمُ الثَّاقِبُ', 'النجم الثاقب وخلق الإنسان من ماء دافق ويوم تبلى السرائر فما له من قوة.', 'في «مجمع البيان»: سورة الطارق مكية، تؤكد حفظ كل نفس وأن الله قادر على رجع الإنسان وإظهار سرائره.'),
  (87, '087', 'سورة الأعلى', 'Al-A\'la', 19, 'مكية', True, 'سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى (1) الَّذِي خَلَقَ فَسَوَّىٰ (2) وَالَّذِي قَدَّرَ فَهَدَىٰ', 'سبح اسم ربك الأعلى وتيسير اليسرى وتذكير من يخشى وصحف إبراهيم وموسى.', 'في «مجمع البيان»: سورة الأعلى مكية، كان النبي ﷺ يحبها لما فيها من تسبيح الرب وتذكير بالآخرة.'),
  (88, '088', 'سورة الغاشية', 'Al-Ghashiyah', 26, 'مكية', True, 'هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ (1) وُجُوهٌ يَوْمَئِذٍ خَاشِعَةٌ (2) عَامِلَةٌ نَّاصِبَةٌ', 'وجوه خاشعة ووجوه ناعمة والتفكر في الإبل والسماء والجبال والأرض سطحت.', 'في «مجمع البيان»: سورة الغاشية مكية، تقارن بين أهل الشقاء وأهل النعيم وتدعو للتفكر الإعجازي.'),
  (89, '089', 'سورة الفجر', 'Al-Fajr', 30, 'مكية', True, 'وَالْفَجْرِ (1) وَلَيَالٍ عَشْرٍ (2) وَالشَّفْعِ وَالْوَتْرِ (3) وَاللَّيْلِ إِذَا يَسْرِ', 'سورة الإمام الحسين عليه السلام والفجر وليال عشر والنفس المطمئنة الراضية.', 'في «مجمع البيان»: سورة الفجر مكية، روي عن الصادق أنها سورة الحسين: {يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ}.'),
  (90, '090', 'سورة البلد', 'Al-Balad', 20, 'مكية', True, 'لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ (1) وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ (2) وَوَالِدٍ وَمَا وَلَدَ', 'القسم بمكة المكرمة وكبد الحياة واقتحام العقبة بفك الرقاب وإطعام ذي مسغبة.', 'في «مجمع البيان»: سورة البلد مكية، تبين أن اقتحام عقبة الآخرة يكون بفك الرقاب وإطعام الجائعين.'),
  (91, '091', 'سورة الشمس', 'Ash-Shams', 15, 'مكية', True, 'وَالشَّمْسِ وَضُحَاهَا (1) وَالْقَمَرِ إِذَا تَلَاهَا (2) وَالنَّهَارِ إِذَا جَلَّاهَا', 'أطول قسم قرآني وفلاح من زكاها وخيبة من دساها وعقر ثمود للناقة.', 'في «مجمع البيان»: سورة الشمس مكية، حوت أحد عشر قسماً متتابعاً على أن الفلاح معقود بتزكية النفس.'),
  (92, '092', 'سورة الليل', 'Al-Layl', 21, 'مكية', True, 'وَاللَّيْلِ إِذَا يَغْشَىٰ (1) وَالنَّهَارِ إِذَا تَجَلَّىٰ (2) وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ', 'شتات السعي بين من أعطى واتقى وصدق بالحسنى ومن بخل واستغنى وكذب.', 'في «مجمع البيان»: سورة الليل مكية، تميز بين درب التيسير لليسرى بالبذل، ودرب العسرى بالبخل.'),
  (93, '093', 'سورة الضحى', 'Ad-Duha', 11, 'مكية', True, 'وَالضُّحَىٰ (1) وَاللَّيْلِ إِذَا سَجَىٰ (2) مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ', 'تسلية قلب النبي {مَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ} وإكرام اليتيم والسائل ونعمة الرب.', 'في «مجمع البيان»: سورة الضحى مكية، نزلت طمأنة للنبي وبشارة بأن عاقبة أمره خير من أولها.'),
  (94, '094', 'سورة الشرح', 'Ash-Sharh', 8, 'مكية', True, 'أَلَمْ نَشْرَحْ لَكَ صَدْرَكَ (1) وَوَضَعْنَا عَنكَ وِزْرَكَ (2) الَّذِي أَنقَضَ ظَهْرَكَ', 'انشراح الصدر ورفع الذكر وبشارة {فَإِنَّ مَعَ الْعُسْرِ يُسْرًا إِنَّ مَعَ الْعُسْرِ يُسْرًا}.', 'في «مجمع البيان»: سورة الشرح مكية، بيّنت مرافقة اليسر لكل عسر، ورفعة مقام النبي الخاتم.'),
  (95, '095', 'سورة التين', 'At-Tin', 8, 'مكية', True, 'وَالتِّينِ وَالزَّيْتُونِ (1) وَطُورِ سِينِينَ (2) وَهَٰذَا الْبَلَدِ الْأَمِينِ', 'خلق الإنسان في أحسن تقويم وإيمانه وعمله الصالح حماية من أسفل سافلين.', 'في «مجمع البيان»: سورة التين مكية، تكرّم جوهر الإنسان وتؤكد خلود أجر المؤمنين الصالحين.'),
  (96, '096', 'سورة العلق', 'Al-\'Alaq', 19, 'مكية', True, 'اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ (1) خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ (2) اقْرَأْ وَرَبُّكَ الْأَكْرَمُ', 'أول ما نزل من القرآن الكريم: اقرأ باسم ربك الذي خلق وسجدة التلاوة والقرب.', 'في «مجمع البيان»: سورة العلق مكية، مطلع النبوة ومشرق الرسالة بالقراءة والعلم وسجود القرب.'),
  (97, '097', 'سورة القدر', 'Al-Qadr', 5, 'مكية', True, 'إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ (1) وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ (2) لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', 'ليلة القدر المباركة التي هي خير من ألف شهر وتنزل الملائكة والروح بالسلام.', 'في «مجمع البيان»: سورة القدر مكية، خلدت ليلة القدر وسلامها الدائم حتى مطلع الفجر العظيم.'),
  (98, '098', 'سورة البينة', 'Al-Bayyinah', 8, 'مدنية', True, 'لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ', 'الإخلاص في الدين وخير البرية وشر البرية ورضي الله عنهم ورضوا عنه.', 'في «مجمع البيان»: سورة البينة مدنية، روي أن خير البرية هم علي وشيعته الفائزون يوم القيامة.'),
  (99, '099', 'سورة الزلزلة', 'Az-Zalzalah', 8, 'مدنية', True, 'إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا (1) وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا (2) وَقَالَ الْإِنسَانُ مَا لَهَا', 'زلزال الأرض وإخراج أثقالها ودقة الميزان بمثقال ذرة خيراً يره أو شراً يره.', 'في «مجمع البيان»: سورة الزلزلة مدنية، تعدل نصف القرآن في الأجر، وتبين عدالة ميزان الذرة.'),
  (100, '100', 'سورة العاديات', 'Al-\'Adiyat', 11, 'مكية', True, 'وَالْعَادِيَاتِ ضَبْحًا (1) فَالْمُورِيَاتِ قَدْحًا (2) فَالْمُغِيرَاتِ صُبْحًا', 'خيل المجاهدين وقدح الشرر في سبيل الله وكنود الإنسان وبشارة نصر ذات السلاسل.', 'في «مجمع البيان»: سورة العاديات نزلت بشارة بنصر الإمام علي وسريته في معركة ذات السلاسل.'),
  (101, '101', 'سورة القارعة', 'Al-Qari\'ah', 11, 'مكية', True, 'الْقَارِعَةُ (1) مَا الْقَارِعَةُ (2) وَمَا أَدْرَاكَ مَا الْقَارِعَةُ (3) يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ', 'قرع القلوب وثقل الموازين بالطاعات في عيشة راضية وخفتها بالهاوية.', 'في «مجمع البيان»: سورة القارعة مكية، تنذر بقرع القيامة للمسامع وتمايز المصائر بحسب الموازين.'),
  (102, '102', 'سورة التكاثر', 'At-Takathur', 8, 'مكية', True, 'أَلْهَاكُمُ التَّكَاثُرُ (1) حَتَّىٰ زُرْتُمُ الْمَقَابِرَ (2) كَلَّا سَوْفَ تَعْلَمُونَ', 'التحذير من التباهي بالأموال والتكاثر حتى زيارة المقابر والسؤال عن النعيم.', 'في «مجمع البيان»: سورة التكاثر مكية، توبخ المنغمسين في التباهي، وتسألهم عن نعمة الإيمان والولاية.'),
  (103, '103', 'سورة العصر', 'Al-\'Asr', 3, 'مكية', True, 'وَالْعَصْرِ (1) إِنَّ الْإِنسَانَ لَفِي خُسْرٍ (2) إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ', 'دستور النجاة الرباني: الإيمان والعمل الصالح والتواصي بالحق والتواصي بالصبر.', 'في «مجمع البيان»: سورة العصر مكية، قال الشافعي لو لم ينزل إلا هذه السورة لكفت الناس في منهج النجاة.'),
  (104, '104', 'سورة الهمزة', 'Al-Humazah', 9, 'مكية', True, 'وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ (1) الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ (2) يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ', 'عاقبة الطعن واللمز وجمع المال وتخليد الحطمة نار الله الموقدة في عمد ممددة.', 'في «مجمع البيان»: سورة الهمزة مكية، تتوعد الذين يغتابون الناس ويلمزونهم ويظنون خلود أموالهم.'),
  (105, '105', 'سورة الفيل', 'Al-Fil', 5, 'مكية', True, 'أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ (1) أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ', 'معجزة حماية الكعبة المشرفة من أبرهة وجيش الفيل بطير أبابيل ترميهم بحجارة.', 'في «مجمع البيان»: سورة الفيل مكية، تخلد نصرة الله لبيته العتيق في عام الفيل عام مولد النبي ﷺ.'),
  (106, '106', 'سورة قريش', 'Quraysh', 4, 'مكية', True, 'لِإِيلَافِ قُرَيْشٍ (1) إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ (2) فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ', 'رحلة الشتاء والصيف ودعوة عبادة رب البيت الذي أطعمهم من جوع وآمنهم من خوف.', 'في «مجمع البيان»: سورة قريش مكية، تذكر أهل مكة بنعمة الأمن والرزق ببركة بيت الله الحرام.'),
  (107, '107', 'سورة الماعون', 'Al-Ma\'un', 7, 'مكية', True, 'أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ (1) فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ (2) وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ', 'التكذيب بالدين وقهر اليتيم والسهو عن الصلاة والرياء ومنع الماعون عن المحتاجين.', 'في «مجمع البيان»: سورة الماعون مكية، تجمع بين التقصير في حق الله بالسهو وفي حق العباد بالمنع.'),
  (108, '108', 'سورة الكوثر', 'Al-Kawthar', 3, 'مكية', True, 'إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ (1) فَصَلِّ لِرَبِّكَ وَانْحَرْ (2) إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ', 'الخير الكثير والذرية الطاهرة لفاطمة الزهراء وانقطاع شانيء النبي الأبتر.', 'في «مجمع البيان»: سورة الكوثر مكية، أبشرت النبي بنهر الكوثر وامتداد نسله الشريف من الزهراء.'),
  (109, '109', 'سورة الكافرون', 'Al-Kafirun', 6, 'مكية', True, 'قُلْ يَا أَيُّهَا الْكَافِرُونَ (1) لَا أَعْبُدُ مَا تَعْبُدُونَ (2) وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ', 'البراءة التامة من الشرك وعبادة الأوثان {لَكُمْ دِينُكُمْ وَلِيَ دِينِ}.', 'في «مجمع البيان»: سورة الكافرون مكية تسمى سورة الإخلاص والبراءة، تقطع أطماع المساومة على التوحيد.'),
  (110, '110', 'سورة النصر', 'An-Nasr', 3, 'مدنية', True, 'إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ (1) وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا (2) فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ', 'آخر سورة كاملة نزولاً: نصر الله ودخول الناس أفواجاً والتسبيح والاستغفار.', 'في «مجمع البيان»: سورة النصر مدنية، آخر سورة نزلت، وفيها إيذان باقتراب أجل النبي بعد تمام الرسالة.'),
  (111, '111', 'سورة المسد', 'Al-Masad', 5, 'مكية', True, 'تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ (1) مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ (2) سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ', 'هلاك أبي لهب وامرأته حمالة الحطب وجزاء العداء لدعوة الحق والرسالة.', 'في «مجمع البيان»: سورة المسد مكية، إعجاز غيبي قاطع بهلاك أبي لهب وزوجته على الكفر والشقاء.'),
  (112, '112', 'سورة الإخلاص', 'Al-Ikhlas', 4, 'مكية', True, 'قُلْ هُوَ اللَّهُ أَحَدٌ (1) اللَّهُ الصَّمَدُ (2) لَمْ يَلِدْ وَلَمْ يُولَدْ (3) وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ', 'نسبة الرب والتوحيد الخالص والصمدية التي تعدل ثلث القرآن الكريم.', 'في «مجمع البيان»: سورة الإخلاص مكية، تعدل ثلث القرآن لجمعها صفات التنزيه والوحدانية التامة.'),
  (113, '113', 'سورة الفلق', 'Al-Falaq', 5, 'مكية', True, 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ (1) مِن شَرِّ مَا خَلَقَ (2) وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ (3) وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ (4) وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'المعوذة الأولى والاستعاذة برب الفلق من شر ما خلق والغاسق والنفاثات والحاسد.', 'في «مجمع البيان»: سورة الفلق مكية، معوذة جليلة للتحصن من شرور المخلوقات والظلمات والسحر والحسد.'),
  (114, '114', 'سورة الناس', 'An-Nas', 6, 'مكية', True, 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ (1) مَلِكِ النَّاسِ (2) إِلَٰهِ النَّاسِ (3) مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ (4) الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ (5) مِنَ الْجِنَّةِ وَالنَّاسِ', 'المعوذة الثانية والاستعاذة بملك الناس وإله الناس من وسواس الخناس في صدور الناس.', 'في «مجمع البيان»: سورة الناس مكية، خاتمة المصحف الشريف في الالتجاء إلى رب الأرباب من كيد الشيطان.')
]

