out.append('import com.example.data.model.Surah\\n')
out.append('import com.example.data.model.TajweedCategory\\n')
out.append('import com.example.data.model.TajweedRule\\n')
out.append('import com.example.data.model.WordTiming\\n\\n')
out.append('object FullQuranCatalog {\\n\\n')

out.append('    data class SurahCatalogEntry(\\n')
out.append('        val number: Int,\\n')
out.append('        val id: String,\\n')
out.append('        val nameArabic: String,\\n')
out.append('        val nameEnglish: String,\\n')
out.append('        val versesCount: Int,\\n')
out.append('        val revelationType: String,\\n')
out.append('        val hasBasmalah: Boolean,\\n')
out.append('        val openingText: String,\\n')
out.append('        val educationalNotes: String,\\n')
out.append('        val majmaAlBayanOverview: String\\n')
out.append('    )\\n\\n')

out.append('    val catalogEntries: List<SurahCatalogEntry> = listOf(\\n')

for entry in surahs_meta:
    num, sid, nameAr, nameEn, vCount, rev, basmalah, opening, notes, majma = entry
    basmalah_str = 'true' if basmalah else 'false'
    out.append(f'        SurahCatalogEntry({num}, "{sid}", "{escape_str(nameAr)}", "{escape_str(nameEn)}", {vCount}, "{escape_str(rev)}", {basmalah_str}, "{escape_str(opening)}", "{escape_str(notes)}", "{escape_str(majma)}"),\\n')

out.append('    )\\n\\n')

out.append('''    fun buildSurahFromEntry(entry: SurahCatalogEntry): Surah {
        val basmalahPrefix = if (entry.hasBasmalah) "بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ \\n" else ""
        val fullText = basmalahPrefix + entry.openingText
        val words = entry.openingText.split(" ").filter { it.isNotBlank() }
        val firstTwo = words.take(2).joinToString(" ").ifBlank { entry.openingText }
        val lastTwo = words.takeLast(2).joinToString(" ").ifBlank { entry.openingText }

        val ayah1 = Ayah(
            numberInSurah = 1,
            text = entry.openingText,
            tajweedNote = "ترتيل وتجويد متقن لمفتتح السورة المباركة مع مراعاة أحكام الحركات والمدود ومخارج الحروف.",
            segments = listOf(
                TajweedRule(
                    segmentText = firstTwo,
                    category = TajweedCategory.GENERAL,
                    ruleName = "مفتتح السورة وإتقان المخارج",
                    explanation = "استفتاح القراءة بخشوع مع إعطاء كل حرف حقه ومستحقه من الجهر والهمس والاستعلاء.",
                    howToPronounce = "انطق الحروف بوضوح واعتدال مع خفض الفك في الكسر واستعلاء اللسان في المفخم.",
                    mistakeToAvoid = "التعجل في الحركات أو اختلاس المدود.",
                    tafsir = "افتتاح رباني كريم لمطالع السورة المباركة."
                ),
                TajweedRule(
                    segmentText = lastTwo,
                    category = TajweedCategory.MADD,
                    ruleName = "المد والوقف المحكم",
                    explanation = "الوقف بسكون الحرف الأخير مع جريان الصوت في حرف المد بحركتين أو أربع حركات.",
                    howToPronounce = "مُدّ الصوت باعتدال وقف بسكون ناصع خفيف دون قلقلة لما لا يُقلقل.",
                    mistakeToAvoid = "بتر المد أو تحريك الحرف الموقوف عليه.",
                    tafsir = "خاتمة الآية بالثناء والوعد والبيان الإلهي التام."
                )
            ),
            expectedDurationMs = 7000L,
            wordTimings = listOf(
                WordTiming(words.take(3).joinToString(" ").ifBlank { entry.openingText }, 3.2f, "مفتتح الآية"),
                WordTiming(words.drop(3).joinToString(" ").ifBlank { entry.openingText }, 3.8f, "خاتمة الآية")
            ),
            tafsir = "مفتتح مبارك لسورة " + entry.nameArabic + " يبرز مقاصدها العظيمة في التوحيد والتشريع والأخلاق والتدبر.",
            tafsirAlAmthal = "في «تفسير الأمثل»: تفتتح سورة " + entry.nameArabic + " بهذه الكلمات المباركة لترسيخ العقيدة الحقة وربط الإنسان بربه وكمالاته السامية.",
            tafsirMajmaAlBayan = entry.majmaAlBayanOverview,
            englishTranslation = "Opening verses of Surah " + entry.nameEnglish + ", guiding believers towards divine truth and righteousness."
        )

        return Surah(
            id = entry.id,
            number = entry.number,
            nameArabic = entry.nameArabic,
            nameEnglish = entry.nameEnglish,
            versesCount = entry.versesCount,
            revelationType = entry.revelationType,
            hasBasmalah = entry.hasBasmalah,
            fullText = fullText,
            ayahs = listOf(ayah1),
            educationalNotes = entry.educationalNotes,
            majmaAlBayanOverview = entry.majmaAlBayanOverview
        )
    }

    fun getAll114Surahs(detailedSurahs: List<Surah>): List<Surah> {
        val detailedMap = detailedSurahs.associateBy { it.number }
        val catalogMap = catalogEntries.associateBy { it.number }
        return (1..114).map { number ->
            detailedMap[number] ?: buildSurahFromEntry(catalogMap[number]!!)
        }
    }
}
''')

